#!/usr/bin/env bash
# Rofi shader picker for Hyprland.
# Lists every shader in ~/.config/hypr/shaders, rewrites shaders.lua, reloads.

DIR="$HOME/.config/hypr/shaders"
CONF="$HOME/.config/hypr/shaders.lua"

choice=$(
  {
    echo "none"
    find "$DIR" -maxdepth 1 -type f \
      \( -iname '*.frag' -o -iname '*.glsl' \) \
      -printf '%f\n' | sort
  } | rofi -dmenu -p "Shader" \
        -theme-str 'listview { lines: 8; columns: 1; }'
) || exit

[ -z "$choice" ] && exit

if [ "$choice" = "none" ]; then
  path=""
else
  path="$DIR/$choice"
fi

cat > "$CONF" <<EOF
-- Auto-generated by ~/.config/scripts/shader.sh (do not edit by hand)
hl.config({
  decoration = {
    screen_shader = "$path",
  },
})
EOF

# Re-evaluate the config so the new shader is picked up
hyprctl reload
